    input6.setValue(" {colSpan:7} ");
    input7.setValue(" {hidden:true} ");
    input8.setValue(' {"category1":["1","2","3"], "category2":["1","2","3"]} ');
    input9.setValue(" [ {value:'합계'}, {inputType:'expression', expression:'SUM(\"category7\")'} ] ");
    //Function 
